usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Evals.Runs.New(
		context.TODO(),
		"eval_id",
		openai.EvalRunNewParams{
			Name: param.NewOpt[string]("string"),
			Metadata: map[string]string{"key": "string"},
			DataSource: openai.CreateEvalJsonlRunDataSource{Type: "jsonl", Source: openai.EvalJsonlFileContentSource{Type: "file_content", Content: []openai.EvalJsonlFileContentSourceContentItem{openai.EvalJsonlFileContentSourceContentItem{Item: map[string]any{"key": nil}, Sample: map[string]any{"key": nil}}}}},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
